  atributos = COALESCE(atributos, '{}'::jsonb) || '{"marca":"Fisher & Paykel","fabricante":"Fisher & Paykel","ref_proveedor":"900MR805","valor_es":"Adaptador de cable calefactor para completar una configuración compatible de circuito RT de doble calefacción.","valor_en":"Heater-wire adapter for a compatible RT-series dual-heated circuit configuration.","beneficios_es":["Identifica un accesorio específico para circuitos RT de doble calefacción.","La presentación de una unidad permite solicitar la referencia exacta dentro de la configuración del circuito."],"beneficios_en":["Identifies a specific accessory for RT-series dual-heated circuits.","The one-unit presentation supports ordering the exact reference within the circuit configuration."],"preguntas_frecuentes_es":[{"q":"¿Para qué circuito se describe el 900MR805?","a":"La documentación de Fisher & Paykel lo identifica como adaptador de cable calefactor para circuitos respiratorios RT de doble calefacción."},{"q":"¿Cuántas unidades contiene?","a":"La referencia se presenta como 1 unidad."},{"q":"¿Se debe confirmar compatibilidad?","a":"Sí. La compatibilidad con circuito, humidificador y configuración clínica se confirma con documentación vigente del fabricante y en la cotización."}],"preguntas_frecuentes_en":[{"q":"Which circuit is the 900MR805 described for?","a":"Fisher & Paykel documentation identifies it as a heater-wire adapter for RT-series dual-heated breathing circuits."},{"q":"How many units are included?","a":"This reference is supplied as one unit."},{"q":"Should compatibility be confirmed?","a":"Yes. Compatibility with the circuit, humidifier and clinical setup must be confirmed against current manufacturer documentation and in the quotation."}],"seo_keywords_es":["adaptador cable calefactor 900MR805","circuito RT doble calefacción Fisher Paykel","accesorio humidificación respiratoria Colombia"],"seo_keywords_en":["900MR805 heater-wire adapter","Fisher Paykel RT dual heated circuit","respiratory humidification accessory Colombia"],"fuentes_auditoria":["https://www.fphcare.com/us/products/devices-and-humidifiers/850-system/infant/circuits-and-accessories/"]}'::jsonb
